import { z } from "zod";
const zBarChartProps = z.object({
    data: z.any(),
    label: z.string().optional(),
    caption: z.string().optional(),
    size: z.enum(["s", "m", "l", "stretch"]).nullish(),
    appearance: z.enum(["default", "card", "well"]).default("default").optional(),
});
export function BarChart(define) {
    return define("BarChart")
        .props(zBarChartProps)
        .render((props) => ({
        id: props.id,
        label: props.label,
        caption: props.caption,
        size: props.size,
        appearance: props.appearance,
        data: props.data,
    }));
}
